import{_ as e,o as t,c as a,Q as n}from"./chunks/framework.b67c47e6.js";const u=JSON.parse('{"title":"Frame Station","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/machines/frame_station/index.md","filePath":"guide/machine_files/machines/frame_station/index.md","lastUpdated":1788855463000}'),i={name:"guide/machine_files/machines/frame_station/index.md"},o=n('<h1 id="frame-station" tabindex="-1">Frame Station <a class="header-anchor" href="#frame-station" aria-label="Permalink to &quot;Frame Station&quot;">​</a></h1><p>The <strong>Frame Station</strong> is a machine type dedicated to the <strong>frame layer</strong> (zone 0) of a wall or floor panel — the structural frame of studs and top/bottom rails, before any cladding goes on.</p><nav class="table-of-contents"><ul><li><a href="#why-a-dedicated-machine-type">Why a dedicated machine type</a></li><li><a href="#configuration-in-produuz-it">Configuration in Produuz.it</a><ul><li><a href="#machine-settings">Machine settings</a></li></ul></li><li><a href="#when-to-enable-the-face-inversions">When to enable the face inversions</a></li></ul></nav><h2 id="why-a-dedicated-machine-type" tabindex="-1">Why a dedicated machine type <a class="header-anchor" href="#why-a-dedicated-machine-type" aria-label="Permalink to &quot;Why a dedicated machine type&quot;">​</a></h2><p>On most lines the frame is built on a Mobi One that also handles the cladding faces. Reusing that machine for the frame meant carrying a lot of settings that don&#39;t apply to the frame, and — more importantly — it forced the <strong>inside</strong> and <strong>outside</strong> faces of the frame to share a single configuration.</p><p>The Frame Station solves this:</p><ul><li>It only exposes the settings that are relevant to the frame layer (framing nails matrix, frame gluing, machine zero, etc.).</li><li>It lets you configure the <strong>inside</strong> and <strong>outside</strong> faces <strong>independently</strong>, using <code>_in</code> / <code>_out</code> options.</li></ul><p>It comes in two versions, matching Mobi One:</p><ul><li><strong>Frame Station V1</strong> — produces <strong>MOB v1</strong> machine files.</li><li><strong>Frame Station V2</strong> — produces <strong>MOB v2</strong> machine files.</li></ul><p>Both accept a machine configuration file upload, just like the Mobi One machines.</p><h2 id="configuration-in-produuz-it" tabindex="-1">Configuration in Produuz.it <a class="header-anchor" href="#configuration-in-produuz-it" aria-label="Permalink to &quot;Configuration in Produuz.it&quot;">​</a></h2><p>In <strong>Company Settings &gt; Production Lines</strong>, add a station with a machine of type <strong>Frame Station</strong> and assign it zone <strong>0</strong>.</p><h3 id="machine-settings" tabindex="-1">Machine settings <a class="header-anchor" href="#machine-settings" aria-label="Permalink to &quot;Machine settings&quot;">​</a></h3><ul><li><strong>General</strong> — Machine zero, blocker heights, max wall length. (No generic direction switches here — orientation is set per face under <strong>Face Inversion</strong>.)</li><li><strong>Framing</strong> — Auto framing nail matrix paddings and minimum CtC, dynamic nail positioning, clamp deactivation. The <strong>Nailing matrix by beam size</strong> opens in its own window from here: the matrix by beam size (height), with the option to read its rows as size ranges (each row covers from its own size up to the next one) instead of exact sizes, and the table of <strong>nail columns by beam width</strong>, with its own ranges option. Both tables are kept sorted when the setup is saved.</li><li><strong>Face Inversion (per face, per axis):</strong> whether each whole face of the frame is machined flipped. When enabled, <strong>all</strong> of that face&#39;s operations — woods, nailing, sawing, drilling, flooring and glue — are mirrored on the chosen axis. X and Y are independent and set per face: <ul><li><strong>Invert X axis (outside face)</strong> / <strong>Invert Y axis (outside face)</strong></li><li><strong>Invert X axis (inside face)</strong> / <strong>Invert Y axis (inside face)</strong></li></ul></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The inversion is applied at the geometry level (the face is read from the matching wrapper/origin), so the whole face stays consistent — it is not a per-operation tweak. It never affects the layer stacking (Z).</p></div><h2 id="when-to-enable-the-face-inversions" tabindex="-1">When to enable the face inversions <a class="header-anchor" href="#when-to-enable-the-face-inversions" aria-label="Permalink to &quot;When to enable the face inversions&quot;">​</a></h2><p>If the two faces of the frame are machined in opposite orientations and one face (typically the <strong>outside</strong>) comes out mirrored relative to the other, enable the X and/or Y inversion for that face. The whole face then follows the orientation the machine uses to machine it.</p>',17),s=[o];function r(h,l,c,d,g,f){return t(),a("div",null,s)}const p=e(i,[["render",r]]);export{u as __pageData,p as default};
